+import { addProviderMarkup } from "@notorganic/core";
+import pricing from "../../../infra/portkey/usage-pricing.json";
+import type { Usage } from "./types";
+
+const object = (value: unknown): Record<string, unknown> | undefined =>
+  value !== null && typeof value === "object" && !Array.isArray(value)
+    ? value as Record<string, unknown> : undefined;
+const count = (value: unknown): value is number =>
+  typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
+
+export function upstreamModel(value: unknown): string | undefined {
+  const model = object(value)?.model;
+  return typeof model === "string" ? model : undefined;
+}
+
+/** Hosted tools and audio have additional rates; token-only evidence is incomplete. */
+export async function supportsTokenPricing(request: Request, path: string): Promise<boolean> {
+  if (!["/chat/completions", "/responses"].includes(path)) return false;
+  if (!request.headers.get("content-type")?.includes("application/json")) return false;
+  const body = object(await request.clone().json());
+  if (!body || body.audio || (body.modalities !== undefined &&
+    (!Array.isArray(body.modalities) || body.modalities.some(value => value !== "text")))) return false;
+  return body.tools === undefined || (Array.isArray(body.tools) &&
+    body.tools.every(tool => object(tool)?.type === "function"));
+}
+
+/** Rates are upstream micro-USD per million tokens, verified against the named config.
+ * Never price a logical alias, an unknown model, or missing/malformed final usage.
+ */
+export function costFromPortkeyUsage(
+  config: string | undefined, model: string | undefined, usage: Usage | undefined,
+): number | undefined {
+  if (config !== pricing.config || !model || !usage || !Object.hasOwn(pricing.models, model)) return;
+  const rate = pricing.models[model as keyof typeof pricing.models];
+  const input = usage.input_tokens ?? usage.prompt_tokens;
+  const output = usage.output_tokens ?? usage.completion_tokens;
+  if (!count(input) || !count(output)) return;
+  if (usage.total_tokens !== undefined &&
+    (!count(usage.total_tokens) || usage.total_tokens !== input + output)) return;
+  const inputDetails = object(usage.input_tokens_details ?? usage.prompt_tokens_details);
+  const outputDetails = object(usage.output_tokens_details ?? usage.completion_tokens_details);
+  const cached = inputDetails?.cached_tokens ?? usage.cached_tokens ?? 0;
+  if (!count(cached) || cached > input) return;
+  // Nonzero audio/cache-write/tool usage cannot be billed at text-only rates.
+  const extra = [inputDetails?.audio_tokens, outputDetails?.audio_tokens,
+    usage.cache_creation_input_tokens, usage.cache_write_tokens];
+  if (extra.some(value => value !== undefined && value !== 0) || usage.server_tool_use) return;
+  const numerator = BigInt(input - cached) * BigInt(rate.input) +
+    BigInt(cached) * BigInt(rate.cachedInput) + BigInt(output) * BigInt(rate.output);
+  const upstream = Number((numerator + 999_999n) / 1_000_000n);
+  if (!Number.isSafeInteger(upstream) || upstream > Number.MAX_SAFE_INTEGER / 2) return;
+  return addProviderMarkup(upstream);
