+function elevenChunk(text: string, offset = 0) {
+  const characters = Array.from(text);
+  return {
+    characters,
+    character_start_times_seconds: characters.map((_, index) => offset + index * 0.1),
+    character_end_times_seconds: characters.map((_, index) => offset + (index + 1) * 0.1),
+  };
+}
+
+describe("ElevenLabs character timing", () => {
+  test("joins provider chunks into word spans without restarting the audio clock", () => {
+    const ranges = mapElevenLabsTimestamps("The light stays on.", [elevenChunk("The li"), elevenChunk("ght stays on.", 0.6)]);
+    expect(ranges.map((range) => [range.sourceStart, range.sourceEnd])).toEqual([[0, 3], [4, 9], [10, 15], [16, 18]]);
+    expect(ranges[1].audioStart).toBeCloseTo(0.4);
+    expect(ranges[1].audioEnd).toBeCloseTo(0.9);
